module x_oracle::pyth_adaptor;

use sui::clock::{Self, Clock};
use sui::table::Table;
use std::type_name::{Self, TypeName};

use pyth::price::{Self, Price};
use pyth::price_info::PriceInfoObject;
use x_oracle::oracle_error;

use x_oracle::price_feed::{Self, PriceFeedComponent};

const U8_MAX: u64 = 255;
const CONF_TOLERANCE_DENOMINATOR: u64 = 10_000;
// A global static pyth price feed delay allowed.
const PRICE_FEED_DELAY_SECONDS: u64 = 30;

public struct PythFeedData has drop, store {
    feed: ID,
    spot_confidence_tolerance_bps: u64,
    ema_confidence_tolerance_bps: u64,
}

public(package) fun get_pyth_price(
    pyth_price_info_object: &PriceInfoObject,
    pyth_feed_data: &PythFeedData,
    clock: &Clock,
): (PriceFeedComponent, PriceFeedComponent) {
    let pyth_price_feed = pyth_price_info_object.get_price_info_from_price_info_object().get_price_feed();

    let ema_price = pyth_price_feed.get_ema_price();
    let spot_price = pyth_price_feed.get_price();

    let (ema_price_value, ema_price_decimals, ema_update_time) = ensure_price_ok(&ema_price, pyth_feed_data.ema_confidence_tolerance_bps, clock);
    let (spot_price_value, spot_price_decimals, spot_update_time) = ensure_price_ok(&spot_price, pyth_feed_data.spot_confidence_tolerance_bps, clock);

    assert!(ema_price_decimals == spot_price_decimals, oracle_error::pyth_spot_ema_price_decimals_not_match());

    let ema_price_value = normalize_decimals(ema_price_value, ema_price_decimals);
    let spot_price_value = normalize_decimals(spot_price_value, ema_price_decimals);

    (
        price_feed::new_component(ema_price_value, ema_update_time),
        price_feed::new_component(spot_price_value, spot_update_time),
    )
}

/// Perform confidence and staleness check on the price, returns the price value and decimal
fun ensure_price_ok(price: &Price, conf_tolerance: u64, clock: &Clock): (u64, u8, u64) {
    let price_value = price.get_price();
    let price_value = price_value.get_magnitude_if_positive();

    let price_decimals = price.get_expo();
    let price_decimals = price_decimals.get_magnitude_if_negative();

    let price_conf = price.get_conf();

    // For price value, the decimals could definitely fit in a u8, otherwise there's a bug
    assert!(price_decimals <= U8_MAX, oracle_error::pyth_price_decimals_too_large());
    assert_price_conf_within_range(price_value, price_conf, conf_tolerance);

    let update_time = assert_price_not_stale(price, clock);

    (price_value, price_decimals as u8, update_time)
}

fun normalize_decimals(price_value: u64, price_decimals: u8): u64 {
    let formatted_decimals = price_feed::decimals();

    let price_value_with_formatted_decimals = if (price_decimals < formatted_decimals) {
        price_value * pow10_u64(formatted_decimals - price_decimals)
    } else {
        // This should rarely happen, since formatted_decimals is 9 and price_decimals is usually smaller than 8
        price_value / pow10_u64(price_decimals - formatted_decimals)
    };
    assert!(price_value_with_formatted_decimals > 0, oracle_error::pyth_price_decimals_too_large());

    price_value_with_formatted_decimals
}

fun assert_price_not_stale(price: &Price, clock: &Clock): u64 {
    let price_updated_time = price::get_timestamp(price);
    let now = clock::timestamp_ms(clock) / 1000;
    // Make sure price is updated within PRICE_FEED_DELAY_SECONDS
    assert!(price_updated_time >= now - PRICE_FEED_DELAY_SECONDS, oracle_error::pyth_price_too_old());
    assert!(price_updated_time <= now , oracle_error::future_pyth_price());

    price_updated_time
}

fun assert_price_conf_within_range(price_value: u64, price_conf: u64, price_conf_tolerance: u64) {
    // Check price confidence is within range
    let price_conf_range = price_conf_tolerance * 100; // multiply by 100, to make it in percentage format
    let price_conf_diff = (price_conf * CONF_TOLERANCE_DENOMINATOR * 100 as u128) / (price_value as u128);
    assert!((price_conf_diff as u64) <= price_conf_range, oracle_error::pyth_price_conf_too_large());
}

public(package) fun assert_pyth_price_info_object(
    self: &PythFeedData,
    price_info_object: &PriceInfoObject,
) {
    assert!(object::id(price_info_object) == self.feed, oracle_error::illegal_pyth_price_object());
}

public(package) fun register_pyth_feed<CoinType>(
    feeds: &mut Table<TypeName, PythFeedData>,
    pyth_info_object: &PriceInfoObject,
    spot_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
    ema_confidence_tolerance_bps: u64,  // per 10,000. so 1 = 0.01%
) {
    assert!(spot_confidence_tolerance_bps <= CONF_TOLERANCE_DENOMINATOR, oracle_error::invalid_conf_range());
    assert!(ema_confidence_tolerance_bps <= CONF_TOLERANCE_DENOMINATOR, oracle_error::invalid_conf_range());

    let coin_type = type_name::with_defining_ids<CoinType>();
    if (feeds.contains(coin_type)) {
        feeds.remove<TypeName, PythFeedData>(coin_type);
    };
    feeds.add(
        coin_type,
        PythFeedData {
            feed: object::id(pyth_info_object),
            spot_confidence_tolerance_bps,
            ema_confidence_tolerance_bps,
        },
    );
}

// Error constant (should be defined at module level)
const EEXP_TOO_LARGE: u64 = 10;

fun pow10_u64(exp: u8): u64 {
    if (exp == 0) 1
    else if (exp == 1) 10
    else if (exp == 2) 100
    else if (exp == 3) 1_000
    else if (exp == 4) 10_000
    else if (exp == 5) 100_000
    else if (exp == 6) 1_000_000
    else if (exp == 7) 10_000_000
    else if (exp == 8) 100_000_000
    else if (exp == 9) 1_000_000_000
    else if (exp == 10) 10_000_000_000
    else if (exp == 11) 100_000_000_000
    else if (exp == 12) 1_000_000_000_000
    else if (exp == 13) 10_000_000_000_000
    else if (exp == 14) 100_000_000_000_000
    else if (exp == 15) 1_000_000_000_000_000
    else if (exp == 16) 10_000_000_000_000_000
    else if (exp == 17) 100_000_000_000_000_000
    else if (exp == 18) 1_000_000_000_000_000_000
    else {
        abort EEXP_TOO_LARGE
    }
}

